#!/usr/bin/env node
// Copies the Idea Validator prompt from the hack-os skill into the server, so the
// site's validator and $hack-os in Codex ask the model exactly the same thing.
//
//   npm run gen:idea-validator     after editing plugin/skills/hack-os/references/idea-validator.md
//
// The prompt is everything below the first "---" line (the lines above it are
// instructions for the Codex session). tests/unit/idea-validator-prompt.test.mts
// fails when the generated file is out of date.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

export const SOURCE = "plugin/skills/hack-os/references/idea-validator.md";
export const TARGET = "src/generated/idea-validator-prompt.ts";

/** The prompt text inside the skill reference. */
export function promptFrom(markdown) {
  const lines = markdown.split("\n");
  const cut = lines.findIndex((l) => l.trim() === "---");
  if (cut < 0) throw new Error(`${SOURCE}: no "---" line before the prompt`);
  return lines.slice(cut + 1).join("\n").trim() + "\n";
}

export function render(prompt) {
  return `// Generated by scripts/gen-idea-validator.mjs from ${SOURCE}. Do not edit by hand.\n\nexport const IDEA_VALIDATOR_PROMPT = ${JSON.stringify(prompt)};\n`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const root = new URL("..", import.meta.url);
  const prompt = promptFrom(readFileSync(new URL(SOURCE, root), "utf8"));
  writeFileSync(new URL(TARGET, root), render(prompt));
  console.log(`wrote ${TARGET} (${prompt.length} chars)`);
}
